def world_to_base(point, odom):
    dx=np.asarray(point[:2])-odom[:2]
    co,si=np.cos(odom[2]),np.sin(odom[2])
    return np.array([co*dx[0]+si*dx[1],-si*dx[0]+co*dx[1],point[2]])

def ik_ee(point_base, qseed, down=True):
    lo=np.array([-10,-2.24,-10,-2.57,-10,-2.09,-10])
    hi=-lo
    def fun(q):
        pos,R=fk(q,ee0)
        err=[15*(pos-np.asarray(point_base))]
        if down: err.append(2*(R@f0-np.array([0,0,-1.])))
        err.append(.03*(q-qseed))
        return np.concatenate(err)
    return least_squares(fun,qseed,bounds=(lo,hi),max_nfev=300).x

def go_ee(world_point, max_steps=50, save=None):
    p=np.asarray(r.get_obs(cameras=['robot_wrist']).meta['proprio']['now'],float)
    local=world_to_base(world_point,p[:3]);qt=ik_ee(local,p[6:13]);print('ik',np.round(local,3),np.round(qt,3))
    return servo_joints(qt,max_steps=max_steps,save=save)
